    /** Adds the INT32 partial sums of the K splits of {@link #gemm} and dequantises them, one thread per output. */
    public static void reduce(KernelContext ctx, IntArray partial, FloatArray c, int m, int n, int splits, FloatArray sx, FloatArray zp, int offset, FloatArray sw,
            IntArray colsum, FloatArray bias, int hasBias) {
        int id = ctx.globalIdx;
        if (id < m * n) {
            int col = id % n;
            int acc = 0;
            for (int z = 0; z < splits; z++) {
                acc += partial.get(z * m * n + id);
            }
            int zero = (int) zp.get(0) - offset;
            float add = hasBias != 0 ? bias.get(col) : 0.0f;
            c.set(id, sx.get(0) * sw.get(col) * (acc - zero * colsum.get(col)) + add);
        }
    }

    /**
     * q = clamp(round_half_even(x / scale) + zp, lo, hi) - offset for x [M, K], packed four to an
     * int along rows padded to kp (padding 0): ONNX QuantizeLinear to UINT8 (lo 0, hi 255, offset
     * 128) or INT8 (-128, 127, 0); scale and zp are device scalars. One thread per int.
     */
    public static void quantize(KernelContext ctx, FloatArray x, IntArray q, FloatArray scale, FloatArray zp, float lo, float hi, int offset, int m, int k, int kp) {
        int id = ctx.globalIdx;
        int lda = kp >> 2;
        if (id < m * lda) {
            int row = id / lda;
            int k0 = (id - row * lda) << 2;
            float s = scale.get(0);
            float zero = zp.get(0);
            int packed = 0;
            for (int j = 0; j < 4; j++) {
                int v = 0;
                if (k0 + j < k) {
                    float f = ElementwiseKernels.roundHalfEven(x.get(row * k + k0 + j) / s) + zero;
                    f = f < lo ? lo : (f > hi ? hi : f);
                    v = (int) f - offset;
                }
                packed |= (v & 0xFF) << (j << 3);
            }
            q.set(id, packed);
        }
    }
